theorem challenge_dudley_vcdim_signclass {X : Type u}
    (V : Submodule ℝ (X → ℝ)) [FiniteDimensional ℝ V] :
    VCDim X (signClass V) ≤ (Module.finrank ℝ V : WithTop ℕ)

theorem challenge_shatter_adversary_equiv {X : Type u}
    (C : ConceptClass X Bool) (S : Finset X) :
    Shatters X C S ↔ AdversaryForcesShattering C S

theorem HasType.atom_inv {Sigma : Theory} {g : String} {I : Interface} {Os : List Interface}
    (h : HasType Sigma (.atom g) I Os) :
    ∃ gen ∈ Sigma.generators, gen.name = g ∧ gen.input = I ∧ gen.outputs = Os

theorem HasType.seq_inv {Sigma : Theory} {p q : Plan} {I : Interface} {Os : List Interface}
    (h : HasType Sigma (.seq p q) I Os) :
    ∃ Js, HasType Sigma p I Js ∧ ∀ J, J ∈ Js → HasType Sigma q J Os

theorem ReaderSel.right_unit {ι : Type u} {α : Type v} {γ : Type w}
    (r : ReaderSel ι α γ) (i₀ : ι) (a : α) :
    (r.bind (fun v => ReaderSel.pure i₀ (fun _ => v))).eval a = r.eval a

private theorem mistakesFromU_init_eq {X : Type u}
    (L : OnlineLearner X Bool) (c : X → Bool) (seq : List X) :
    mistakesFromU L L.init c seq = L.mistakes c seq

private theorem shatters_restrict {X : Type u} {C : ConceptClass X Bool}
    {S : Finset X} (hshat : Shatters X C S) {x : X} (hx : x ∈ S) (b : Bool) :
    Shatters X {c ∈ C | c x = b} (S.erase x)

private theorem adversary_from_shatters {X : Type u}
    (L : OnlineLearner X Bool) (s : L.State)
    {C : ConceptClass X Bool} {S : Finset X}
    (hshat : Shatters X C S) :
    ∃ (seq : List X) (c : X → Bool), c ∈ C ∧
      mistakesFromU L s c seq = S.card

private theorem vcdim_le_of_mistake_bounded {X : Type u}
    {C : ConceptClass X Bool} {M : ℕ}
    (hM : MistakeBounded X Bool C M) : VCDim X C ≤ ↑M

private theorem ldim_restriction_le {X : Type} {C : ConceptClass X Bool}
    {x : X} {y : Bool} :
    LittlestoneDim X {c ∈ C | c x = y} ≤ LittlestoneDim X C

private theorem ldim_branch_lower_bound {X : Type} {V : ConceptClass X Bool}
