theorem LTree.isShattered_truncate {X : Type} {C : ConceptClass X Bool}
    {m : ℕ} (T : LTree X m) (hT : T.isShattered C) {n : ℕ} (h : n ≤ m) :
    (T.truncate h).isShattered C

private theorem exists_shattered_of_ldim_ge {X : Type} {C : ConceptClass X Bool}
    {d : ℕ} (h : LittlestoneDim X C ≥ ↑(↑d : WithTop ℕ)) :
    ∃ T : LTree X d, T.isShattered C

private theorem adversary_lower_bound {X : Type} {C : ConceptClass X Bool}
    {n : ℕ} (T : LTree X n) (hT : T.isShattered C)
    {M : ℕ} (hM : MistakeBounded X Bool C M) : n ≤ M

lemma hypothesisEnvelope_sub {X : Type u} {C : ConceptClass X Bool}
    (L : ProperFiniteSupportLearner X C) (c : X → Bool) (Y : Finset X)
    (h : X → Bool) (hh : h ∈ hypothesisEnvelope L c Y) : h ∈ C

private theorem sum_boolToSign_cancel {m : ℕ} (i : Fin m) (f : SignVector m → ℝ)
    (hf : ∀ σ σ', (∀ k, k ≠ i → σ k = σ' k) → f σ = f σ') :
    ∑ σ : SignVector m, boolToSign (σ i) * f σ = 0

private theorem empRad_nonneg {X : Type u} (C : ConceptClass X Bool) {m : ℕ}
    (hm : m ≠ 0) (xs : Fin m → X) :
    0 ≤ EmpiricalRademacherComplexity X C xs

private theorem shatters_subset {X : Type u} (C : ConceptClass X Bool)
    (T S : Finset X) (hTS : S ⊆ T) (hT : Shatters X C T) :
    Shatters X C S

private theorem growth_function_le_sum_choose_set {X : Type u}
    (C : ConceptClass X Bool) (d m : ℕ) (_hdm : d ≤ m) (hvc : VCDim X C = ↑d) :
    GrowthFunction X C m ≤ ∑ i ∈ Finset.range (d + 1), Nat.choose m i

private theorem vcdim_zero_concepts_agree (X : Type u) (C : ConceptClass X Bool)
    (hd : VCDim X C = (0 : ℕ)) (h₁ h₂ : Concept X Bool) (hh₁ : h₁ ∈ C) (hh₂ : h₂ ∈ C)
    (x : X) : h₁ x = h₂ x

theorem shatters_realize {X : Type u} {C : ConceptClass X Bool} {T : Finset X}
    (hT : Shatters X C T) (f : ↥T → Bool) :
    ∃ c ∈ C, ∀ x : ↥T, c (x : X) = f x

private theorem thresholdX_not_shatter_pair {X : Type u} {φ : ℕ ↪ X}
    {S : Finset X} (hcard : 2 ≤ S.card) :
    ¬ Shatters X (thresholdClassX φ) S

private theorem mistakesFromG_init_eq {X : Type u}
    (L : OnlineLearner X Bool) (c : X → Bool) (seq : List X) :
    mistakesFromG L L.init c seq = L.mistakes c seq

theorem MistakeTree.fromList_shattered {X : Type u} [DecidableEq X] {C : ConceptClass X Bool}
    (l : List X) (hl : l.Nodup) (hS : Shatters X C l.toFinset) :
    (MistakeTree.fromList l).isShattered X C

theorem adversary_core {X : Type}
    (L : OnlineLearner X Bool) (s : L.State)
    {C : ConceptClass X Bool} {n : ℕ}
    (T : LTree X n) (hT : T.isShattered C) (hne : C.Nonempty) :
    ∃ (seq : List X) (c : X → Bool), c ∈ C ∧
      L.mistakesFrom s c seq = n

theorem mistakesFrom_init_eq {X : Type}
    (L : OnlineLearner X Bool) (c : X → Bool) (seq : List X) :
    L.mistakesFrom L.init c seq = L.mistakes c seq

theorem versionSpace_subset {X : Type} {C : ConceptClass X Bool}
    {history : List (X × Bool)} :
    versionSpace C history ⊆ C

theorem target_in_versionSpace {X : Type} {C : ConceptClass X Bool}
    {c : X → Bool} (hcC : c ∈ C) {history : List (X × Bool)}
    (hcons : ∀ p ∈ history, c p.1 = p.2) :
    c ∈ versionSpace C history

theorem versionSpace_append {X : Type} {C : ConceptClass X Bool}
    {history : List (X × Bool)} {x : X} {y : Bool} :
    versionSpace C (history ++ [(x, y)]) ⊆ versionSpace C history

theorem ldim_versionSpace_le {X : Type} {C : ConceptClass X Bool}
    {history : List (X × Bool)} :
    LittlestoneDim X (versionSpace C history) ≤ LittlestoneDim X C

private lemma growth_function_le_two_pow {X : Type u}
    (C : ConceptClass X Bool) (n : ℕ) :
    GrowthFunction X C n ≤ 2 ^ n

theorem finite_vc_union_decomposition_budget {C D : ConceptClass X Bool} {dC dD : ℕ}
    (hC : VCDim X C ≤ (dC : WithTop ℕ)) (hD : VCDim X D ≤ (dD : WithTop ℕ)) :
    VCDim X (C ∪ D) ≤ ((dC + dD + 1 : ℕ) : WithTop ℕ)

theorem packing_card_le_growthFunction {C : ConceptClass X Bool} {S : Finset X}
    {P : Finset (X → Bool)} {δ : ℝ} (hδ : 0 ≤ δ) (hP : IsPacking C S P δ) :
    P.card ≤ GrowthFunction X C S.card

private theorem growthFunction_eq (C : ConceptClass X Bool) (m : ℕ) :
    GrowthFunction X C m =
      sSup (Set.range fun S : { S : Finset X // S.card = m } => (restrictionSet C S.val).ncard)

theorem isEpsilonNet_of_isEpsilonApprox (C : ConceptClass X Bool) {P N : Finset X} {ε : ℝ}
    (hε : 0 < ε) (hN : 0 < N.card) (happrox : IsEpsilonApprox C P N (ε / 2)) :
    IsEpsilonNet C P N ε

theorem framework_vcDim_dualClass_le {C : ConceptClass X Bool} {d : ℕ}
    (hd : VCDim X C ≤ (d : WithTop ℕ)) :
    VCDim ↥C (dualClass C) ≤ ((2 ^ (d + 1) - 1 : ℕ) : WithTop ℕ)

theorem framework_vcDim_union_le {C D : ConceptClass X Bool} {dC dD : ℕ}
    (hC : VCDim X C ≤ (dC : WithTop ℕ)) (hD : VCDim X D ≤ (dD : WithTop ℕ)) :
    VCDim X (C ∪ D) ≤ ((dC + dD + 1 : ℕ) : WithTop ℕ)

theorem vcDim_submodular_imp_subadditive_biUnion (h : VCDimSubmodular X) {ι : Type v}
    (s : Finset ι) (C : ι → ConceptClass X Bool) :
    VCDim X (⋃ i ∈ s, C i) ≤ ∑ i ∈ s, VCDim X (C i)

private theorem gf_eq (C : ConceptClass X Bool) (m : ℕ) :
    GrowthFunction X C m =
      sSup (Set.range fun S : { S : Finset X // S.card = m } => (restrictionSet C S.val).ncard)

theorem shatters_erase_slice {C : ConceptClass X Bool} {S : Finset X}
    (hshat : Shatters X C S) {x : X} (hx : x ∈ S) (b : Bool) :
    Shatters X {c ∈ C | c x = b} (S.erase x)

theorem shatters_forces_all_mistakes {C : ConceptClass X Bool} {S : Finset X}
    (hshat : Shatters X C S) (L : OnlineLearner X Bool) (s : L.State) :
    ∃ (seq : List X) (c : X → Bool), c ∈ C ∧ mistakesAlong L s c seq = S.card

private theorem gf_eq (C : ConceptClass X Bool) (m : ℕ) :
    GrowthFunction X C m =
      sSup (Set.range fun S : { S : Finset X // S.card = m } => (restrictionSet C S.val).ncard)

theorem hasPolyDegree_union {C D : ConceptClass X Bool} {rC rD : ℝ}
    (hC : HasPolyDegree C rC) (hD : HasPolyDegree D rD) :
    HasPolyDegree (C ∪ D) (max rC rD)

theorem vcDensity_union_le_max {C D : ConceptClass X Bool}
    (hC : VCDim X C < ⊤) (hD : VCDim X D < ⊤) :
    vcDensity (C ∪ D) ≤ max (vcDensity C) (vcDensity D)

theorem coveringNumber_le_card_restrictionSet (C : ConceptClass X Bool) (S : Finset X) {ε : ℝ}
    (hε : 0 ≤ ε) :
    CoveringNumber X C (sampleHammingDist S) ε ≤ (restrictionSet C S).ncard

theorem coveringNumber_le_growthFunction (C : ConceptClass X Bool) (S : Finset X) {ε : ℝ}
    (hε : 0 ≤ ε) :
    CoveringNumber X C (sampleHammingDist S) ε ≤ GrowthFunction X C S.card

theorem dualClass_shatters_imp_shatters {d : ℕ}
    (S : Finset ↥C) (hS : Shatters ↥C (dualClass C) S) (hcard : 2 ^ (d + 1) ≤ S.card) :
    ∃ T : Finset X, T.card = d + 1 ∧ Shatters X C T

theorem vcDim_union_le {C D : ConceptClass X Bool} {dC dD : ℕ}
    (hC : VCDim X C ≤ (dC : WithTop ℕ)) (hD : VCDim X D ≤ (dD : WithTop ℕ)) :
    VCDim X (C ∪ D) ≤ ((dC + dD + 1 : ℕ) : WithTop ℕ)

theorem pow_le_vcDim_imp_le_vcDim_dualClass {C : ConceptClass X Bool} {k : ℕ}
    (T : Finset X) (hT : Shatters X C T) (hcard : 2 ^ k ≤ T.card) :
    (k : WithTop ℕ) ≤ VCDim ↥C (dualClass C)

theorem log₂_vcDim_le_vcDim_dualClass {C : ConceptClass X Bool} {d : ℕ}
    (hd : VCDim X C = (d : WithTop ℕ)) (hd0 : 0 < d) :
    (Nat.log 2 d : WithTop ℕ) ≤ VCDim ↥C (dualClass C)

theorem coveringNumber_ge_pow_of_shatters {C : ConceptClass X Bool} {S : Finset X}
    (hS : Shatters X C S) {ε : ℝ} (hε0 : 0 ≤ ε) (hε1 : ε < 1) :
    2 ^ S.card ≤ CoveringNumber X C (sampleHammingDist S) ε

theorem additivityDefect_le_one {C D : ConceptClass X Bool} {dC dD : ℕ}
    (hC : VCDim X C ≤ (dC : WithTop ℕ)) (hD : VCDim X D ≤ (dD : WithTop ℕ)) :
    VCDim X (C ∪ D) ≤ ((dC + dD + 1 : ℕ) : WithTop ℕ)
